class Solution{public:vector<string>wordBreak(string s,vector<string>&w){unordered_set<string>q(w.begin(),w.end());unordered_map<int,vector<string>>m;function<vector<string>(int)>f=[&](int i){if(m.count(i))return m[i];vector<string>r;if(i==s.size()){r.push_back("");return r;}for(int j=i+1;j<=s.size();j++)if(q.count(s.substr(i,j-i)))for(auto&t:f(j))r.push_back(s.substr(i,j-i)+(t.empty()?"":" ")+t);return m[i]=r;};return f(0);}};
